using Microsoft.ML;
using Microsoft.ML.Data;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

var mlContext = new MLContext(seed: 0);
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");

// Load CSV with Churned as string, then map "Yes"/"No" → bool Label
var rawData = mlContext.Data.LoadFromTextFile<CustomerDataRaw>(
    dataPath, hasHeader: true, separatorChar: ',');

var mappingPipeline = mlContext.Transforms.CustomMapping<CustomerDataRaw, ChurnLabel>(
    (input, output) => { output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase); },
    contractName: "ChurnMapping");

var pipeline = mappingPipeline
    .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerDataRaw.Region)))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(CustomerDataRaw.Age),
        nameof(CustomerDataRaw.Income),
        "RegionEncoded",
        nameof(CustomerDataRaw.PurchaseHistory)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Label", featureColumnName: "Features"));

var model = pipeline.Fit(rawData);

app.MapGet("/", () => "Churn Predictor API – POST to /predict");

app.MapPost("/predict", (CustomerInput input) =>
{
    var engine = mlContext.Model.CreatePredictionEngine<CustomerDataRaw, ChurnPrediction>(model);
    var data = new CustomerDataRaw
    {
        Age = input.Age,
        Income = input.Income,
        Region = input.Region,
        PurchaseHistory = input.PurchaseHistory,
        Churned = "No"
    };
    var result = engine.Predict(data);
    return Results.Ok(new
    {
        Churned = result.PredictedLabel ? "Yes" : "No",
        Probability = Math.Round(result.Probability, 4)
    });
});

app.Run();

